import json,re,os,glob
cmds=[]
for f in ["settings.json","settings.local.json"]:
    try: d=json.load(open(f))
    except Exception as e: print(f,e); continue
    for ev,arr in d.get("hooks",{}).items():
        for m in arr:
            for h in m.get("hooks",[]): cmds.append((f,ev,h.get("command","")))
paths=set()
for f,ev,c in cmds:
    for p in re.findall(r'[\w./~$"{}-]+\.(?:ts|py|sh|js|mjs|ps1)',c):
        p=p.replace('"','').replace("${HOME}","$HOME").replace("$HOME",os.path.expanduser("~")).replace("~",os.path.expanduser("~"))
        paths.add((ev,p))
for ev,p in sorted(paths):
    if os.path.isfile(p) and re.search(r"settings(\.local)?\.json",open(p,errors="ignore").read()):
